import{_ as a,o as t,c as r,a0 as o}from"./chunks/framework.BxCN1dRw.js";const p=JSON.parse('{"title":"文档教程","description":"","frontmatter":{"docLocale":"zh","counterpart":"/en/docs/"},"headers":[],"relativePath":"docs/index.md","filePath":"docs/index.md"}'),d={name:"docs/index.md"};function i(c,e,n,s,l,h){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="文档教程" tabindex="-1">文档教程 <a class="header-anchor" href="#文档教程" aria-label="Permalink to &quot;文档教程&quot;">​</a></h1><p>这里是在线教程与生成参考的统一入口。全部内容与仓库源码同源：教程步骤可跟做，<a href="./../reference/api">API 合同</a>与<a href="./../reference/config">配置参考</a>从实现自动生成，页面页脚标注每页验收时对应的源码版本。</p><ul><li>从<a href="./../getting-started/quickstart">快速开始</a>用一条真实请求把模板跑起来。</li><li><a href="./../tutorials/first-request">跟做教程</a>按功能逐篇展开注册、会话、文档、附件、导出、成员、审计等真实链路。</li><li><a href="./../reference/api">生成参考</a>提供当前 API operationId 与配置项默认值，始终与源码一致。</li><li>准备发布自己的站点时，阅读<a href="./../getting-started/publish-docs">发布教程站点</a>。</li></ul><h2 id="语言与范围" tabindex="-1">语言与范围 <a class="header-anchor" href="#语言与范围" aria-label="Permalink to &quot;语言与范围&quot;">​</a></h2><p>站点提供简体中文与英文两种语言，通过导航栏的语言菜单切换，同一章节互相对应；尚未翻译的章节在英文导航中不出现，也不会伪装出英文页面。搜索覆盖本站全部已发布文档与生成参考，不包含应用内数据。中文是默认阅读语言；分享链接按路径决定语言，不随设备语言自动重定向。</p><h2 id="维护双语章节" tabindex="-1">维护双语章节 <a class="header-anchor" href="#维护双语章节" aria-label="Permalink to &quot;维护双语章节&quot;">​</a></h2><p>新增页面必须成对提交中文与英文版本：中文源文件旁放置同名 <code>.en.md</code> 文件，并在 <code>docs/site.json</code> 中登记同一稳定 <code>id</code>、两组标题与分组标签。发布检查会校验章节配对、链接与生成参考；完整步骤见<a href="./../getting-started/publish-docs">发布教程站点</a>。既有尚未翻译的章节作为迁移项登记在 <code>docs/site.json</code>，由后续实现票随功能一起交付英文版本。</p><hr><p>源码版本：<code>6ad98d9f41e8</code> · <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/6ad98d9f41e8b0842c3a68362d0d94bddb022c0a/docs/getting-started/documentation.md" target="_blank" rel="noreferrer">本页 Markdown</a></p>',9)])])}const u=a(d,[["render",i]]);export{p as __pageData,u as default};
